-- ══════════════════════════════════════════════════════════════════════════
-- Part A — User.hideReadingHistory column (PERF-06)
-- ══════════════════════════════════════════════════════════════════════════

ALTER TABLE "User" ADD COLUMN "hideReadingHistory" BOOLEAN NOT NULL DEFAULT false;

-- ══════════════════════════════════════════════════════════════════════════
-- Part B — AiAuditLog PARTITION BY RANGE (createdAt) (PERF-05)
-- ══════════════════════════════════════════════════════════════════════════

-- Step 1: rename existing heap table
ALTER TABLE "AiAuditLog" RENAME TO "AiAuditLog_old";

-- Rename indexes/constraints so the new partitioned table can re-use canonical names
ALTER INDEX "AiAuditLog_pkey" RENAME TO "AiAuditLog_old_pkey";

-- Step 2: create new partitioned parent table
-- Composite PK (id, createdAt) required by PG for partition key inclusion.
CREATE TABLE "AiAuditLog" (
    "id" TEXT NOT NULL,
    "scope" TEXT NOT NULL,
    "scopeId" TEXT NOT NULL,
    "issueType" TEXT NOT NULL,
    "severity" "Severity" NOT NULL,
    "analysis" TEXT NOT NULL,
    "recommendation" TEXT NOT NULL,
    "resolved" BOOLEAN NOT NULL DEFAULT false,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "AiAuditLog_pkey" PRIMARY KEY ("id", "createdAt")
) PARTITION BY RANGE ("createdAt");

-- Step 3: create monthly partitions from 2024-01 through 2028-12 (60 partitions)
DO $$
DECLARE
    i INT;
    start_month DATE;
    end_month DATE;
    partition_name TEXT;
BEGIN
    -- 60 months: from 2024-01 (i=0) through 2028-12 (i=59)
    FOR i IN 0..59 LOOP
        start_month := (DATE '2024-01-01' + (i || ' month')::interval)::DATE;
        end_month   := start_month + INTERVAL '1 month';
        partition_name := 'AiAuditLog_y'
                          || to_char(start_month, 'YYYY')
                          || '_m'
                          || to_char(start_month, 'MM');
        EXECUTE format(
            'CREATE TABLE %I PARTITION OF "AiAuditLog" FOR VALUES FROM (%L) TO (%L);',
            partition_name,
            start_month,
            end_month
        );
    END LOOP;
END $$;

-- Step 4: copy existing data from old table to partitioned table
INSERT INTO "AiAuditLog" SELECT * FROM "AiAuditLog_old";

-- Step 5: drop old heap table (CASCADE drops carried-along indexes)
DROP TABLE "AiAuditLog_old" CASCADE;

-- Step 6: create index for common query pattern (scope + scopeId lookups)
CREATE INDEX "AiAuditLog_scope_scopeId_idx" ON "AiAuditLog" ("scope", "scopeId");
